with kept_keys as (select location from departments except select location from departments where location in ('Tokyo', 'Berlin', 'Chiang Mai')), kept_rows as (select s.* from departments s join kept_keys k on s.location = k.location), with_windows as (select id, dept_name, location, budget, rank() over (partition by dept_name, location order by budget nulls last) as budget_rank, round(budget / sum(budget) over (partition by dept_name), 4) as budget_share, round(budget / sum(budget) over (partition by location), 4) as budget_share_2, max(budget) over (partition by dept_name) as dept_name_max_budget from kept_rows), base as (select id, budget, budget_rank, budget_share, budget_share_2, dept_name_max_budget, cast(budget as int) as budget_int, substring(location, 1, 3) as location_prefix from with_windows where location is not null), with_windows_departments as (select id, budget, budget_rank, budget_share, budget_share_2, dept_name_max_budget, budget_int, location_prefix, percent_rank() over (order by budget desc) as budget_percent_rank, percent_rank() over w_grp as budget_rank_percent_rank from base window w_grp as (order by budget_rank nulls last)) select case when budget_share_2 >= 0.61 then 'PREMIUM' else 'STANDARD' end as budget_share_2_tier, approx_percentile(budget_share_2, array(0.25, 0.5, 0.75)) as budget_share_2_quartiles, count(distinct id) as distinct_ids, count(*) as cnt, approx_percentile(dept_name_max_budget, 0.5) as dept_name_max_budget_p50 from with_windows_departments group by cube (case when budget_share_2 >= 0.61 then 'PREMIUM' else 'STANDARD' end) order by budget_share_2_tier desc nulls last;
